_speed - lead_speed\\n            ttc = float('inf')\\n            if relative_speed \u003e 0 and distance \u003e 0:\\n                ttc = distance / relative_speed\\n            \\n            if ttc \u003c self.ttc_threshold:\\n                mode = 'emergency'\\n            else:\\n                mode = 'follow'\\n        \\n        if mode == 'cruise':\\n            error = self.set_speed - ego_speed\\n            acceleration_cmd = self.pid_speed.compute(error, dt)\\n            self.pid_distance.reset()\\n            \\n        elif mode == 'follow':\\n            desired_distance = self.min_distance + (self.time_headway * ego_speed)\\n            error = distance - desired_distance\\n            distance_error = error\\n            acceleration_cmd = self.pid_distance.compute(error, dt)\\n            self.pid_speed.reset()\\n            \\n        elif mode == 'emergency':\\n            acceleration_cmd = self.max_decel\\n            self.pid_speed.reset()\\n            self.pid_distance.reset()\\n            if distance is not None:\\n                desired_distance = self.min_distance + (self.time_headway * ego_speed)\\n                distance_error = distance - desired_distance\\n\\n        # Clamp acceleration\\n        acceleration_cmd = max(self.max_decel, min(self.max_accel, acceleration_cmd))\\n        \\n        return acceleration_cmd, mode, distance_error\\nEOF\\n\",\n      \"duration\": 0.1\n    }\n  ]\n}",
